import gurobipy as gp
from gurobipy import GRB
platform_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
genre_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
platforms = []
capacities = {}
for rec in platform_records:
    pid = rec['values']['PlatformId']
    platforms.append(pid)
    capacities[pid] = int(rec['values']['Capacity'])
genres = []
values = {}
weights = {}
for rec in genre_records:
    gname = rec['values']['ProductName']
    genres.append(gname)
    values[gname] = int(rec['values']['Value'])
    weights[gname] = int(rec['values']['Weight'])
if len(platforms) == 0 or len(genres) == 0:
    raise ValueError('Missing platforms or genres in LEGACY_RECORDS')
for pid in platforms:
    if pid not in capacities:
        raise ValueError(f'Missing capacity for platform {pid}')
for gname in genres:
    if gname not in values or gname not in weights:
        raise ValueError(f'Missing value or weight for genre {gname}')
m = gp.Model('VideoGameStore_Listing')
x_vars = m.addVars(platforms, genres, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[g] * x_vars[p, g] for p in platforms for g in genres)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((weights[g] * x_vars[p, g] for g in genres)) <= capacities[p] for p in platforms), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
